.row { display: flex; justify-content: space-between; gap: 12px; color: var(--muted); font-size: .9rem; }
.value-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.value-item { padding: 16px; border-radius: 14px; border: 1px solid var(--border); background: #0f1417; }
