.sidebar { position: sticky; top: 78px; align-self: start; padding: 16px; }
.filter-btn {
  width: 100%; text-align: left; background: transparent; border: 1px solid transparent;
  color: var(--muted); padding: 10px; border-radius: 10px; cursor: pointer; transition: .2s;
