.filter-btn.active, .filter-btn:hover { color: var(--text); border-color: var(--border); background: rgba(0,230,184,0.07); }
.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.pricing { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.price-card { padding: 20px; position: relative; overflow: hidden; }
.save-badge { position: absolute; top: 14px; right: 14px; background: var(--accent); color: #042019; border-radius: 999px; padding: 6px 10px; font-weight: 700; font-size: .8rem; }
.toggle { display: inline-flex; gap: 8px; background: #0d1215; border: 1px solid var(--border); border-radius: 999px; padding: 6px; }
.toggle button { border: 0; background: transparent; color: var(--muted); padding: 8px 14px; border-radius: 999px; cursor: pointer; }
.toggle button.active { background: var(--accent); color: #042019; font-weight: 700; }
.benefits { display: grid; grid-template-columns: repeat(2,1fr); gap: 12px; }
.faq-item { border-bottom: 1px solid var(--border); }
.faq-q { width: 100%; text-align: left; border: 0; background: transparent; color: var(--text); padding: 14px 0; font-size: 1rem; cursor: pointer; }
.faq-a { color: var(--muted); padding: 0 0 12px; display: none; }
.faq-item.open .faq-a { display: block; }
.controls { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
.controls button { border: 1px solid var(--border); background: #0f1417; color: var(--muted); padding: 8px 12px; border-radius: 999px; cursor: pointer; }
.controls button.active { color: var(--text); border-color: var(--accent); }
.masonry { column-count: 3; column-gap: 14px; }
.project { break-inside: avoid; margin-bottom: 14px; overflow: hidden; }
.project .img { width: 100%; background-size: cover; background-position: center; border-radius: 14px 14px 0 0; }
.project .body { padding: 12px; }
.auth-wrap { min-height: calc(100vh - 200px); display: grid; place-items: center; }
.form { width: min(500px, 100%); padding: 24px; }
.field { display: grid; gap: 6px; margin-bottom: 12px; }
.field input {
  width: 100%; border: 1px solid var(--border); border-radius: 12px; padding: 11px 12px;
  background: #0c1114; color: var(--text);
}
.field input:focus { outline: 2px solid var(--ring); border-color: transparent; }
.password-wrap { position: relative; }
.password-toggle { position: absolute; right: 10px; top: 50%; transform: translateY(-50%); border: 0; background: transparent; color: var(--muted); cursor: pointer; }
.footer { margin-top: 56px; padding: 26px 0 34px; border-top: 1px solid var(--border); background: #070a0b; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.footer h4 { margin: 0 0 10px; font-size: .95rem; }
.footer ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 7px; }
.footer a { color: var(--muted); font-size: .9rem; }
.footer a:hover { color: var(--text); }
